<script lang="ts">
	import { data } from '#lib/stores/data';
	import { recordData, statusInfo } from '#lib/workflow';
	import { CalendarDays, ChevronRight, Clock3, MapPin, UsersRound } from '@lucide/svelte';
	let view = $state<'week'|'all'>('week');
	function jobs() {
		const start = new Date(); start.setHours(0,0,0,0);
		const end = new Date(start); end.setDate(end.getDate()+7);
		return Object.entries($data.projects).map(([key,record]) => ({key,record,value:recordData(record)}))
			.filter(row => row.value.montage_date || ['ONAYLANDI','URETIMDE','MONTAJ_PLANLANDI','MONTAJDA'].includes(row.value.status))
			.filter(row => view==='all' || !row.value.montage_date || (new Date(row.value.montage_date)>=start && new Date(row.value.montage_date)<=end))
			.sort((a,b)=>String(a.value.montage_date||'9999').localeCompare(String(b.value.montage_date||'9999')));
	}
</script>
<svelte:head><title>Montaj Planı | Tayfun Yapı</title></svelte:head>
<div class="page"><header><div><span>OPERASYON</span><h1>Montaj Planı</h1><p>Planlanmayı bekleyen işler, ekipler ve haftalık program.</p></div><div class="switch"><button class:active={view==='week'} onclick={()=>view='week'}>Bu hafta</button><button class:active={view==='all'} onclick={()=>view='all'}>Tümü</button></div></header>
	<section class="stats"><div><CalendarDays/><span>Planlı montaj<strong>{jobs().filter(j=>j.value.montage_date).length}</strong></span></div><div><Clock3/><span>Tarih bekleyen<strong>{jobs().filter(j=>!j.value.montage_date).length}</strong></span></div><div><UsersRound/><span>Aktif ekip<strong>{new Set(jobs().map(j=>j.value.montage_team).filter(Boolean)).size}</strong></span></div></section>
	<section class="schedule">{#each jobs() as job}{@const status=statusInfo(job.value.status)}<a href={`/projects/${job.key}`}><div class="date" class:pending={!job.value.montage_date}>{#if job.value.montage_date}<strong>{new Date(job.value.montage_date).getDate()}</strong><span>{new Date(job.value.montage_date).toLocaleDateString('tr-TR',{month:'short',weekday:'short'})}</span>{:else}<Clock3/><span>Tarih seç</span>{/if}</div><div class="info"><strong>{job.value.name||'Adsız iş'}</strong><span>{job.value.customer||'Müşteri seçilmedi'}</span></div><div class="team"><UsersRound size={16}/><span>{job.value.montage_team||'Ekip seçilmedi'}</span></div><div class="location"><MapPin size={16}/><span>{job.value.address||'Adres proje dosyasında'}</span></div><span class="status" style={`--status:${status.color}`}>{status.label}</span><ChevronRight size={19}/></a>{:else}<div class="empty"><CalendarDays size={38}/><strong>Montaj programı boş</strong><span>İş detayından tarih ve ekip belirleyebilirsiniz.</span></div>{/each}</section>
</div>
<style>
	.page{max-width:1380px;margin:auto;padding:30px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}header>div>span{font-size:10px;font-weight:800;color:#0f7c80;letter-spacing:1px}h1{font-size:28px;margin:2px 0}header p{margin:0;color:#78838e}.switch{display:flex;padding:3px;background:#e6eaed;border-radius:6px}.switch button{height:34px;border:0;background:none;border-radius:4px;padding:0 14px;font-weight:700;color:#6c7781;cursor:pointer}.switch button.active{background:#fff;color:#0f7c80;box-shadow:0 1px 3px #0001}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:12px}.stats>div{display:flex;align-items:center;gap:12px;padding:15px;background:#fff;border:1px solid #dfe4e8;border-radius:7px;color:#0f7c80}.stats span,.stats strong{display:block}.stats span{font-size:11px;color:#7b8791}.stats strong{font-size:20px;color:#25313a}.schedule{background:#fff;border:1px solid #dfe4e8;border-radius:7px;overflow:hidden}.schedule>a{display:grid;grid-template-columns:70px minmax(180px,1fr) 170px 220px 140px 20px;gap:14px;align-items:center;padding:13px 16px;border-bottom:1px solid #edf0f2;color:inherit;text-decoration:none}.schedule>a:hover{background:#f8fbfb}.date{width:58px;height:58px;border-radius:6px;background:#e8f5f4;color:#0f7c80;display:grid;place-items:center;align-content:center}.date strong{font-size:21px;line-height:1}.date span{font-size:9px;text-transform:uppercase}.date.pending{background:#f5f6f7;color:#8a949c}.info strong,.info span{display:block}.info span,.team,.location{font-size:11px;color:#7d8992}.team,.location{display:flex;align-items:center;gap:7px}.status{padding:6px 9px;border-radius:5px;background:color-mix(in srgb,var(--status) 12%,white);color:var(--status);font-size:10px;font-weight:800}.empty{min-height:280px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;color:#8a949e}.empty strong{color:#374151}
	@media(max-width:1000px){.schedule>a{grid-template-columns:65px 1fr 150px 120px 20px}.location{display:none}}
	@media(max-width:650px){.page{padding:18px 12px 90px}header{align-items:flex-start}header p{display:none}.stats{grid-template-columns:1fr 1fr}.stats>div:last-child{grid-column:1/-1}.schedule>a{grid-template-columns:58px 1fr 20px;padding:11px}.team,.status{grid-column:2/3}.location{display:none}}
</style>
